PROCESS_POOL_THRESHOLD = 200


class ScanResult:
    def __init__(self, root: Path, files: List[Dict], source: str, repo_name: str):
        self.root = root
        self.files = files
        self.source = source
        self.repo_name = repo_name


def _normalize_extensions(raw: object, defaults: Dict[str, str]) -> Dict[str, str]:
    normalized: Dict[str, str] = {}
    if isinstance(raw, dict):
        items = raw.items()
        for key, value in items:
            ext = str(key).strip()
            if not ext:
                continue
            if not ext.startswith("."):
                ext = f".{ext}"
            desc = value if isinstance(value, str) and value.strip() else defaults.get(ext, "")
            normalized[ext] = desc
    elif isinstance(raw, list):
        for item in raw:
            ext = str(item).strip()
            if not ext:
                continue
            if not ext.startswith("."):
                ext = f".{ext}"
            normalized[ext] = defaults.get(ext, "")
    return normalized or defaults.copy()


def _normalize_excludes(raw: object) -> Set[str]:
    if not isinstance(raw, list):
        return set()
    return {str(item).strip() for item in raw if str(item).strip()}


def _load_extension_config(root: Path) -> Dict[str, object]:
    config_path = root / ".ai-docs.yaml"
    defaults = {
        "code_extensions": CODE_EXTENSION_DESCRIPTIONS,
        "doc_extensions": DOC_EXTENSION_DESCRIPTIONS,
        "config_extensions": CONFIG_EXTENSION_DESCRIPTIONS,
    }

    if not config_path.exists():
        payload = {
            "code_extensions": defaults["code_extensions"],
            "doc_extensions": defaults["doc_extensions"],
            "config_extensions": defaults["config_extensions"],
        }
        config_path.write_text(
            yaml.safe_dump(payload, allow_unicode=True, sort_keys=False),
            encoding="utf-8",
        )
        return {**{key: value.copy() for key, value in defaults.items()}, "exclude": set()}

    try:
        raw = yaml.safe_load(config_path.read_text(encoding="utf-8", errors="ignore")) or {}
    except yaml.YAMLError:
        return {**{key: value.copy() for key, value in defaults.items()}, "exclude": set()}

    if not isinstance(raw, dict):
        return {**{key: value.copy() for key, value in defaults.items()}, "exclude": set()}

    code_raw = raw.get("code_extensions") or {}
    doc_raw = raw.get("doc_extensions") or {}
    config_raw = raw.get("config_extensions") or {}
    exclude_raw = raw.get("exclude") or []

    return {
        "code_extensions": _normalize_extensions(code_raw, defaults["code_extensions"]),
        "doc_extensions": _normalize_extensions(doc_raw, defaults["doc_extensions"]),
        "config_extensions": _normalize_extensions(config_raw, defaults["config_extensions"]),
        "exclude": _normalize_excludes(exclude_raw),
    }


def _build_default_include_patterns(extension_config: Dict[str, object]) -> Set[str]:
    extensions: Set[str] = set()
    for key in ("code_extensions", "doc_extensions", "config_extensions"):
        extensions.update(extension_config.get(key, {}).keys())
    return {f"*{ext}" for ext in extensions} | FIXED_INCLUDE_PATTERNS


def _compile_pathspec(patterns: Optional[Set[str]]) -> Optional[pathspec.PathSpec]:
    if not patterns:
        return None
    return pathspec.PathSpec.from_lines("gitignore", sorted(patterns))


def _load_ignore_specs(root: Path) -> List[pathspec.PathSpec]:
    specs: List[pathspec.PathSpec] = []
    for name in (".gitignore", ".build_ignore"):
        ignore_file = root / name
        if not ignore_file.exists():
            continue
        patterns = ignore_file.read_text(encoding="utf-8", errors="ignore").splitlines()
        specs.append(pathspec.PathSpec.from_lines("gitignore", patterns))
    return specs


def _matches_any_spec(rel_path: str, specs: Optional[pathspec.PathSpec]) -> bool:
    return bool(specs and specs.match_file(rel_path))


def _should_include(
    rel_path: str,
    include_spec: Optional[pathspec.PathSpec],
    exclude_spec: Optional[pathspec.PathSpec],
    ignore_specs: Sequence[pathspec.PathSpec],
) -> bool:
    for spec in ignore_specs:
        if spec.match_file(rel_path):
            return False
    if _matches_any_spec(rel_path, exclude_spec):
        return False
    if not include_spec:
        return True
    return _matches_any_spec(rel_path, include_spec)


def _should_prune_dir(
    rel_dir: str,
    exclude_spec: Optional[pathspec.PathSpec],
    ignore_specs: Sequence[pathspec.PathSpec],
) -> bool:
    dir_name = rel_dir.rsplit("/", 1)[-1]
    if dir_name in PRUNABLE_DIR_NAMES:
        return True
    if any(rel_dir == path or rel_dir.endswith(f"/{path}") for path in PRUNABLE_DIR_PATHS):
        return True
    if _matches_any_spec(rel_dir, exclude_spec):
        return True
    for spec in ignore_specs:
        if spec.match_file(rel_dir):
            return True
    return False


def _load_file_record(task: Tuple[str, str, int]) -> Optional[Dict]:
    abs_path_str, rel_path_str, max_size = task
    abs_path = Path(abs_path_str)

    try:
        if abs_path.is_symlink():
            return None
        size = abs_path.stat().st_size
        if max_size and size > max_size:
            return None
        if is_binary_file(abs_path):
            return None
        content = read_text_file(abs_path)
    except OSError:
        return None

    content_snippet = content[:4000]
    file_type = classify_type(abs_path)
    domains = detect_domains(abs_path, content_snippet)
    if is_infra(domains):
        file_type = "infra"

    return {
        "path": rel_path_str,
        "abs_path": abs_path,
        "size": size,
        "content": content,
        "type": file_type,
        "domains": sorted(domains),
    }


def _scan_directory(
    root: Path,
    include_spec: Optional[pathspec.PathSpec],
    exclude_spec: Optional[pathspec.PathSpec],
    max_size: int,
    workers: int,
) -> List[Dict]:
    files: List[Dict] = []
    ignore_specs = _load_ignore_specs(root)
    tasks: List[Tuple[str, str, int]] = []

    for dirpath, dirnames, filenames in os.walk(root):
        current_dir = Path(dirpath)
        dirnames[:] = [
            dirname
            for dirname in dirnames
            if not _should_prune_dir(
                to_posix((current_dir / dirname).relative_to(root)),
                exclude_spec,
                ignore_specs,
            )
        ]
        for filename in filenames:
            abs_path = current_dir / filename
            rel_path_str = to_posix(abs_path.relative_to(root))
            if not _should_include(rel_path_str, include_spec, exclude_spec, ignore_specs):
                continue
            tasks.append((str(abs_path), rel_path_str, max_size))

    if workers > 1 and len(tasks) >= PROCESS_POOL_THRESHOLD:
        with ProcessPoolExecutor(max_workers=workers) as executor:
            for record in executor.map(_load_file_record, tasks):
                if record is not None:
                    files.append(record)
        return files

    for task in tasks:
        record = _load_file_record(task)
        if record is not None:
            files.append(record)
    return files


def _clone_repo(repo_url: str) -> Tuple[Path, str]:
    tmpdir = Path(tempfile.mkdtemp(prefix="ai_docs_"))
    try:
        subprocess.check_call(["git", "clone", "--depth", "1", repo_url, str(tmpdir)])
    except Exception as exc:
        shutil.rmtree(tmpdir, ignore_errors=True)
        raise RuntimeError(f"Failed to clone repo: {exc}")
    repo_name = repo_url.rstrip("/").split("/")[-1].replace(".git", "")
    return tmpdir, repo_name


def scan_source(
    source: str,
    include: Optional[Set[str]] = None,
    exclude: Optional[Set[str]] = None,
    max_size: int = 200_000,
    workers: int = 5,
) -> ScanResult:
    exclude = set(exclude or DEFAULT_EXCLUDE_PATTERNS)

    if is_url(source):
        root, repo_name = _clone_repo(source)
        extension_config = _load_extension_config(root)
        include = include or _build_default_include_patterns(extension_config)
        exclude = set(exclude) | set(extension_config.get("exclude", set()))
        include_spec = _compile_pathspec(include)
        exclude_spec = _compile_pathspec(exclude)
        files = _scan_directory(root, include_spec, exclude_spec, max_size, workers)
        return ScanResult(root=root, files=files, source=source, repo_name=repo_name)

    root = Path(source).expanduser().resolve()
    if not root.exists():
        raise FileNotFoundError(f"Source path not found: {root}")
    extension_config = _load_extension_config(root)
    include = include or _build_default_include_patterns(extension_config)
    exclude = set(exclude) | set(extension_config.get("exclude", set()))
    include_spec = _compile_pathspec(include)
    exclude_spec = _compile_pathspec(exclude)
    files = _scan_directory(root, include_spec, exclude_spec, max_size, workers)
    return ScanResult(root=root, files=files, source=str(root), repo_name=root.name)

from functools import lru_cache
from typing import List

import tiktoken


class _ByteEncoding:
    def encode(self, text: str):
        return list(text.encode("utf-8", errors="ignore"))

    def decode(self, tokens):
        return bytes(tokens).decode("utf-8", errors="ignore")


@lru_cache(maxsize=None)
def get_encoding(model: str):
    try:
        return tiktoken.encoding_for_model(model)
    except KeyError:
        try:
            return tiktoken.get_encoding("cl100k_base")
        except Exception:
            return _ByteEncoding()


@lru_cache(maxsize=2048)
def _encode_tokens(text: str, model: str) -> tuple[int, ...]:
    enc = get_encoding(model)
    return tuple(enc.encode(text))


@lru_cache(maxsize=512)
def _chunk_text_cached(text: str, model: str, max_tokens: int) -> tuple[str, ...]:
    enc = get_encoding(model)
    tokens = _encode_tokens(text, model)
    chunks = []
    for i in range(0, len(tokens), max_tokens):
        chunk = tokens[i:i + max_tokens]
        chunks.append(enc.decode(chunk))
    return tuple(chunks)


def count_tokens(text: str, model: str) -> int:
    return len(_encode_tokens(text, model))


def chunk_text(text: str, model: str, max_tokens: int) -> List[str]:
    return list(_chunk_text_cached(text, model, max_tokens))

import json
from pathlib import Path
from typing import Dict, Tuple

from .utils import ensure_dir


class CacheManager:
    def __init__(self, cache_dir: Path):
        self.cache_dir = cache_dir
        ensure_dir(self.cache_dir)
        self.index_path = self.cache_dir / "index.json"
        self.llm_cache_path = self.cache_dir / "llm_cache.json"

    def load_index(self) -> Dict:
        if not self.index_path.exists():
            return {"files": {}, "sections": {}}
        return json.loads(self.index_path.read_text(encoding="utf-8", errors="ignore"))

    def save_index(self, data: Dict) -> None:
        self.index_path.write_text(json.dumps(data, ensure_ascii=False, indent=2), encoding="utf-8")

    def load_llm_cache(self) -> Dict[str, str]:
        if not self.llm_cache_path.exists():
            return {}
        raw = self.llm_cache_path.read_text(encoding="utf-8", errors="ignore")
        if not raw.strip():
            return {}
        try:
            return json.loads(raw)
        except json.JSONDecodeError:
            bad_path = self.llm_cache_path.with_suffix(".json.bad")
            try:
                bad_path.write_text(raw, encoding="utf-8")
            except OSError:
                pass
            return {}

    def save_llm_cache(self, data: Dict[str, str]) -> None:
        snapshot = dict(data)
        self.llm_cache_path.write_text(json.dumps(snapshot, ensure_ascii=False, indent=2), encoding="utf-8")

    def diff_files(self, current_files: Dict[str, Dict]) -> Tuple[Dict, Dict, Dict, Dict]:
        prev = self.load_index().get("files", {})
        added = {}
        modified = {}
        deleted = {}
        unchanged = {}

        for path, meta in current_files.items():
            if path not in prev:
                added[path] = meta
                continue
            if prev[path].get("hash") != meta.get("hash"):
                modified[path] = meta
            else:
                unchanged[path] = meta

        for path, meta in prev.items():
            if path not in current_files:
                deleted[path] = meta

        return added, modified, deleted, unchanged

import hashlib
import os
from pathlib import Path


def sha256_bytes(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def sha256_text(text: str) -> str:
    return sha256_bytes(text.encode("utf-8", errors="ignore"))


def read_text_file(path: Path) -> str:
    return path.read_text(encoding="utf-8", errors="ignore")


def safe_slug(path: str) -> str:
    return "".join(c if c.isalnum() else "_" for c in path).strip("_").lower()


def ensure_dir(path: Path) -> None:
    path.mkdir(parents=True, exist_ok=True)


def is_binary_file(path: Path, sample_size: int = 2048) -> bool:
    try:
        with path.open("rb") as f:
            chunk = f.read(sample_size)
        if b"\x00" in chunk:
            return True
        return False
    except OSError:
        return True


def is_url(value: str) -> bool:
    return value.startswith("http://") or value.startswith("https://") or value.startswith("git@")


def to_posix(path: Path) -> str:
    return path.as_posix()

import json
from pathlib import Path
from typing import Dict, List, Set, Tuple

import tomli

from .utils import read_text_file


SECTION_TITLES = {
    "architecture": "Архитектура",
    "runtime": "Запуск и окружение",
    "dependencies": "Зависимости",
    "testing": "Тестирование",
    "conventions": "Соглашения",
    "glossary": "Глоссарий",
}

DOMAIN_TITLES = {
    "kubernetes": "Kubernetes",
    "helm": "Helm",
    "terraform": "Terraform",
    "ansible": "Ansible",
    "docker": "Docker",
    "ci": "CI/CD",
    "observability": "Observability",
    "service_mesh": "Service Mesh / Ingress",
    "data_storage": "Data / Storage",
}


def is_test_path(path: str) -> bool:
    parts = Path(path).parts
    if any(part in {"test", "tests", "__tests__"} for part in parts):
        return True
    name = Path(path).name
    return name.startswith("test_") or name.endswith("_test.py")


def collect_dependencies(files: Dict[str, Dict]) -> List[str]:
    deps: List[str] = []
    for path, meta in files.items():
        if path.endswith("pyproject.toml"):
            try:
                data = tomli.loads(meta["content"])
                deps_map = data.get("tool", {}).get("poetry", {}).get("dependencies", {})
                deps.extend([f"{k} {v}" for k, v in deps_map.items()])
            except Exception:
                continue
        if path.endswith("requirements.txt"):
            lines = [line.strip() for line in meta["content"].splitlines() if line.strip() and not line.strip().startswith("#")]
            deps.extend(lines)
        if path.endswith("package.json"):
            try:
                data = json.loads(meta["content"])
                for section in ("dependencies", "devDependencies"):
                    for k, v in data.get(section, {}).items():
                        deps.append(f"{k} {v}")
            except Exception:
                continue
    return sorted(set(deps))


def collect_test_info(files: Dict[str, Dict]) -> Tuple[List[str], List[str]]:
    test_paths = sorted([path for path in files if is_test_path(path)])
    commands: List[str] = []
    for path, meta in files.items():
        if path.endswith("pyproject.toml"):
            try:
                data = tomli.loads(meta["content"])
                scripts = data.get("tool", {}).get("poetry", {}).get("scripts", {})
                if scripts:
                    commands.append("poetry run pytest")
            except Exception:
                continue
        if path.endswith("setup.cfg"):
            commands.append("pytest")
        if path.endswith("tox.ini"):
            commands.append("tox")
        if path.endswith("package.json"):
            try:
                data = json.loads(meta.get("content", ""))
                scripts = data.get("scripts", {})
                if "test" in scripts:
                    commands.append("npm test")
            except Exception:
                continue

    return test_paths, sorted(set(commands))


def render_testing_section(test_paths: List[str], commands: List[str]) -> str:
    if not test_paths:
        return "Тесты не обнаружены."
    tests_md = "\n".join(f"- `{p}`" for p in test_paths)
    commands_md = "\n".join(f"- `{c}`" for c in commands) if commands else "- (команда запуска не определена)"
    return (
        "## Найденные тесты\n\n"
        f"{tests_md}\n\n"
        "## Как запускать\n\n"
        f"{commands_md}\n"
    )


def render_project_configs_index(config_nav_paths: List[str]) -> str:
    if not config_nav_paths:
        return "Конфигурационные файлы не обнаружены."
    toc_lines = "\n".join(
        [
            f"- [{Path(p).with_suffix('').as_posix()}]({Path(p).as_posix()[len('configs/'):] if p.startswith('configs/') else p})"
            for p in sorted(config_nav_paths)
        ]
    )
    return f"## Файлы конфигурации\n\n{toc_lines}\n"


def strip_duplicate_heading(content: str, title: str) -> str:
    lines = content.splitlines()
    if not lines:
        return content
    first = lines[0].strip()
    if first.startswith("#") and first.lstrip("#").strip().lower() == title.strip().lower():
        return "\n".join(lines[1:]).lstrip()
    return content


def first_paragraph(text: str) -> str:
    lines: List[str] = []
    for raw in text.splitlines():
        line = raw.strip()
        if not line:
            if lines:
                break
            continue
        if line.startswith("#") or line.startswith("```"):
            continue
        lines.append(line)
        if len(lines) >= 2:
            break
    return " ".join(lines).strip()


def get_cached_text(meta: Dict[str, object], path_key: str, text_key: str) -> str:
    text = meta.get(text_key)
    if isinstance(text, str) and text:
        return text
    path = meta.get(path_key)
    if not isinstance(path, str) or not path:
        return ""
    text = read_text_file(Path(path))
    meta[text_key] = text
    return text


def build_docs_index(
    docs_dir: Path,
    docs_files: Dict[str, str],
    file_map: Dict[str, Dict],
    section_titles: Dict[str, str],
) -> Dict[str, object]:
    existing_files: Set[str] = set()
    if docs_dir.exists():
        for path in docs_dir.rglob("*.md"):
            try:
                existing_files.add(path.relative_to(docs_dir).as_posix())
            except Exception:
                continue
    sections = []
    for key, title in section_titles.items():
        path = f"{key}.md"
        if path in docs_files or path in existing_files:
            sections.append({"id": key, "title": title, "path": path})
    if "configs/index.md" in docs_files or "configs/index.md" in existing_files:
        sections.append({"id": "configs", "title": "Конфигурация проекта", "path": "configs/index.md"})

    modules = []
    for path, meta in file_map.items():
        if is_test_path(path):
            continue
        summary_path = meta.get("module_summary_path")
        if not summary_path:
            continue
        module_rel = Path("modules") / Path(path).with_suffix("")
        module_rel_str = module_rel.as_posix() + ".md"
        summary_text = get_cached_text(meta, "module_summary_path", "module_summary_text")
        modules.append(
            {
                "name": Path(path).with_suffix("").as_posix(),
                "path": module_rel_str,
                "source_path": path,
                "summary": first_paragraph(summary_text),
            }
        )

    configs = []
    for path, meta in file_map.items():
        if meta.get("type") != "config":
            continue
        summary_path = meta.get("config_summary_path")
        if not summary_path:
            continue
        config_rel = Path("configs/files") / Path(path)
        config_rel_str = config_rel.as_posix().replace(".", "__") + ".md"
        summary_text = get_cached_text(meta, "config_summary_path", "config_summary_text")
        configs.append(
            {
                "name": Path(path).as_posix(),
                "path": config_rel_str,
                "source_path": path,
                "summary": first_paragraph(summary_text),
            }
        )

    return {
        "sections": sections,
        "modules": modules,
        "configs": configs,
        "files": sorted(set(docs_files.keys()) | existing_files | {"_index.json"}),
    }
